import { test, expect } from '@playwright/test';

test.describe('Promo Code Application', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000/checkout');
    await page.waitForLoadState('networkidle');
  });

  test('should apply valid promo code and display discounted total', async ({ page }) => {
    // Add item to cart if not already present
    const addToCartButton = page.getByRole('button', { name: /add to cart/i });
    if (await addToCartButton.isVisible()) {
      await addToCartButton.click();
    }

    // Navigate to checkout
    await page.goto('http://localhost:3000/checkout');
    await page.waitForLoadState('networkidle');

    // Verify initial total is displayed
    const initialTotal = page.getByText(/total.*\$\d+\.\d+/i);
    await expect(initialTotal).toBeVisible();
    const initialTotalText = await initialTotal.textContent();
    const initialAmount = parseFloat(initialTotalText?.match(/\$(\d+\.\d+)/)?.[1] || '0');

    // Locate and fill promo code input
    const promoCodeInput = page.getByLabel(/promo code/i);
    await expect(promoCodeInput).toBeVisible();
    await promoCodeInput.fill('SAVE20');

    // Apply promo code
    const applyButton = page.getByRole('button', { name: /apply|submit/i });
    await applyButton.click();

    // Wait for discount to be applied
    await page.waitForTimeout(1000);

    // Verify success message appears
    const successMessage = page.getByText(/promo code applied|discount applied|success/i);
    await expect(successMessage).toBeVisible();

    // Verify discounted total is displayed and is less than initial
    const discountedTotal = page.getByText(/total.*\$\d+\.\d+/i);
    await expect(discountedTotal).toBeVisible();
    const discountedTotalText = await discountedTotal.textContent();
    const discountedAmount = parseFloat(discountedTotalText?.match(/\$(\d+\.\d+)/)?.[1] || '0');

    // Assert that discounted amount is less than initial amount
    expect(discountedAmount).toBeLessThan(initialAmount);

    // Verify discount breakdown is shown
    const discountLine = page.getByText(/discount|savings/i);
    await expect(discountLine).toBeVisible();
  });

